pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
    }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint128).max);
        uint256 lenBefore = LogFile(c.Log()).HistoryLength();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        uint256 lenAfter = LogFile(c.Log()).HistoryLength();
        assertTrue(lenAfter == lenBefore + 1);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
    function HistoryLength() public view returns (uint256) {
        return History.length;
    }
}

