pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        // Constrain to reasonable range to avoid overflow padding
        bound(amount1, 1, 1e30);
        bound(amount2, 1, 1e30);
        // Ensure actor is not the zero address and not a precompile
        vm.assume(actor != address(0) && actor.code.length == 0);

        // Initialize the contracts properly so Deposit can be called
        c.SetLogFile(address(new LogFile()));
        c.SetMinSum(0);
        c.Initialized();

        // Step 1: Perform an initial deposit to ensure Log is non-empty and LastMsg is set.
        vm.deal(actor, amount1);
        vm.prank(actor);
        c.Deposit{value: amount1}();

        // Record the LastMsg.Val after first deposit
        (, , uint valAfterFirstDeposit, ) = c.Log().LastMsg();

        // Step 2: Perform a second deposit; the bug will skip AddMessage, leaving LastMsg.Val unchanged.
        vm.deal(actor, amount2);
        vm.prank(actor);
        c.Deposit{value: amount2}();

        (, , uint valAfterSecondDeposit, ) = c.Log().LastMsg();

        // Invariant: After the second deposit, the LastMsg.Val must equal the second deposit amount.
        // In the correct contract, AddMessage updates LastMsg.Val to amount2.
        // In the buggy contract, AddMessage is skipped, so LastMsg.Val remains amount1.
        assertTrue(valAfterSecondDeposit == amount2);
    }
}

